<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{ $group->name }} · Digital Flipbook</title><style>*{box-sizing:border-box}body{margin:0;background:#0f172a;color:#fff;font-family:Inter,Arial,sans-serif}.bar{min-height:72px;display:flex;align-items:center;justify-content:space-between;gap:18px;padding:14px 24px;background:#fff;color:#0f172a}.brand{display:flex;align-items:center;gap:12px;font-weight:800}.brand img{max-height:42px;max-width:150px;object-fit:contain}.stage{min-height:calc(100vh - 72px);display:grid;place-items:center;padding:24px}.page{position:relative;width:min(1100px,100%);height:min(72vh,760px);background:#111827;box-shadow:0 24px 70px #0008;overflow:hidden}.page img{width:100%;height:100%;object-fit:contain}.nav{position:absolute;inset:0;display:flex;align-items:center;justify-content:space-between;pointer-events:none}.nav button{pointer-events:auto;border:0;background:#0009;color:#fff;width:52px;height:64px;font-size:26px;cursor:pointer}.meta{position:absolute;inset:auto 0 0;padding:28px 20px 15px;background:linear-gradient(transparent,#000b);display:flex;justify-content:space-between;font-size:13px}.empty{text-align:center;color:#cbd5e1}@media(max-width:640px){.bar{padding:12px 15px}.stage{padding:0}.page{height:calc(100vh - 72px)}.nav button{width:44px}}</style></head><body><header class="bar"><div class="brand">@if($branding['logo_url'])<img src="{{ $branding['logo_url'] }}" alt="{{ $branding['business_name'] }} logo">@endif<span>{{ $branding['business_name'] }}</span></div><strong>{{ $group->name }}</strong></header><main class="stage">@if($photos->isEmpty())<div class="empty"><h1>No photos in this Flipbook yet</h1><p>Check back when the gallery is ready.</p></div>@else<div class="page"><img id="photo" src="{{ $photos[0]['url'] }}" alt="{{ $photos[0]['name'] }}"><div class="nav"><button type="button" aria-label="Previous page" onclick="move(-1)">‹</button><button type="button" aria-label="Next page" onclick="move(1)">›</button></div><div class="meta"><span id="name">{{ $photos[0]['name'] }}</span><span id="count">1 / {{ $photos->count() }}</span></div></div>@endif</main>@if($photos->isNotEmpty())<script>const pages=@json($photos->values()),image=document.getElementById('photo'),nameEl=document.getElementById('name'),count=document.getElementById('count');let page=0;function move(step){page=(page+step+pages.length)%pages.length;image.src=pages[page].url;image.alt=pages[page].name;nameEl.textContent=pages[page].name;count.textContent=`${page+1} / ${pages.length}`}addEventListener('keydown',e=>{if(e.key==='ArrowLeft')move(-1);if(e.key==='ArrowRight'||e.key===' ')move(1)})</script>@endif</body></html>
